schema.sdl:
type Query {
  viewer: User!
  species(id: ID!): Species
  searched(term: String!): [Species!]!
  speciesList(first: Int, after: String, last: Int, before: String): SpeciesConnection!
  speciesFiltered(filter: SpeciesFilter!): [Species!]!
}

type Mutation {
  favorite(id: ID!): Species!
}

type User {
  id: ID!
  name: String!
  favorite: Species
}

type Species {
  id: ID!
  name: String!
  move: SpeciesMove
  friends: [Species!]
}

type SpeciesMove {
  name: String!
  power: Int
}

type SpeciesConnection {
  edges: [SpeciesEdge!]!
  pageInfo: PageInfo!
}

type SpeciesEdge {
  node: Species!
  cursor: String!
}

type PageInfo {
  hasNextPage: Boolean!
  endCursor: String
}

input SpeciesFilter {
  term: String!
  limit: Int
}

inputs.text:
fragment SpeciesCard on Species {
  id
  name
  move {
    name
  }
}

fragment SpeciesHeader on Species {
  id
  name
}

mutation FavoriteMutation($id: ID!) @dedupe(cancelFirst: true, match: variables) {
  favorite(id: $id) {
    id
    ...SpeciesCard
  }
}

query SpeciesSearch($term: String!, $withMove: Boolean!) @cache(policy: CacheOnly) {
  searched(term: $term) @loading(count: 3) {
    id
    ...SpeciesCard
    ...SpeciesHeader @include(if: $withMove)
    ... on Species @defer(label: "friends") {
      friends @stream(initialCount: 2) {
        id
      }
    }
  }
}

query ViewerQuery($cursor: String) {
  viewer {
    id
    name
    favorite {
      ...SpeciesCard
    }
  }
  speciesList(first: 10, after: $cursor) @paginate(name: "AllSpecies") {
    edges {
      node {
        id
        ...SpeciesCard
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

